function currentHelpKey(){const key=activeNavKey();return helpGuides[key]?key:"home"}
function openHelpGuide(){const guide=helpGuides[currentHelpKey()]||helpGuides.home;const overview=guide.what?`<section class="help-overview"><div><b>O que é</b><p>${esc(guide.what)}</p></div><div><b>Para que serve</b><p>${esc(guide.purpose)}</p></div></section>`:`<p class="help-intro">${esc(guide.intro)}</p>`;document.body.insertAdjacentHTML("beforeend",`<div class="help-overlay" id="help-overlay"><aside class="help-drawer" role="dialog" aria-modal="true" aria-labelledby="help-title"><header class="help-header"><div><span>?</span><b>GUIA DE AJUDA</b></div><button type="button" id="close-help" aria-label="Fechar guia">×</button></header><div class="help-body"><h2 id="help-title">${esc(guide.title)}</h2>${guide.subtitle?`<p class="help-subtitle">${esc(guide.subtitle)}</p>`:""}${overview}<span class="help-section-title">Como usar</span><ol class="help-steps">${guide.steps.map(([title,text],index)=>`<li><span>${index+1}</span><div><b>${esc(title)}</b><p>${esc(text)}</p></div></li>`).join("")}</ol><section class="help-tip"><b>💡 ${esc(guide.tipLabel||"Dica metodológica")}</b><p>${esc(guide.tip)}</p></section></div></aside></div>`);const overlay=$("#help-overlay"),close=()=>{overlay.remove();document.body.classList.remove("help-open")};document.body.classList.add("help-open");$("#close-help").onclick=close;overlay.addEventListener("click",event=>{if(event.target===overlay)close()});document.addEventListener("keydown",function escapeHelp(event){if(event.key==="Escape"&&document.body.contains(overlay)){close();document.removeEventListener("keydown",escapeHelp)}});$("#close-help").focus()}
function activeNavKey(){const base=route().split("?")[0].split("/")[0];return base==="session"?"sessions":base==="screen"?"screening":base}
function analysisFlow(active){const current=analysisWorkflow.findIndex(([key])=>key===active);if(current<0)return"";return `<nav class="analysis-flow" aria-label="Fluxo contínuo da análise"><div class="analysis-flow-head"><div><b>Fluxo da análise</b><small>Da criação da sessão ao mapa bibliométrico</small></div><span>Etapa ${current+1} de ${analysisWorkflow.length}</span></div><div class="analysis-flow-track">${analysisWorkflow.map(([key,label,icon],index)=>`<a href="#/${key}" class="analysis-flow-step ${index<current?"complete":index===current?"current":"upcoming"}" ${index===current?'aria-current="step"':""}><span>${index<current?"✓":icon}</span><b>${label}</b><small>${index+1}</small></a>`).join("")}</div></nav>`}

function appFooter(){return `<footer class="footer"><img class="footer-logo" src="icons/decb-uern.png" alt="Logomarca do Departamento de Ciências Biológicas da UERN"><div>Universidade do Estado do Rio Grande do Norte — UERN © 2026</div><div>Desenvolvido pelo Prof. José Egberto Mesquita Pinto Júnior com a ferramenta de IA ChatGPT</div><div class="footer-actions"><span class="footer-version" aria-label="Versão da EcoMétrica">EcoMétrica 3.0 · Versão 58</span><button type="button" class="footer-cite-button" id="cite-ecometrica">Como citar a EcoMétrica</button></div></footer>`}
function citationAccessDate(){return new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"short",year:"numeric"}).format(new Date()).replaceAll(" de "," ").replace(".","")}
function ecometricaCitations(){const accessed=citationAccessDate(),iso=new Date().toISOString().slice(0,10),url="https://egbertomesquita-cmd.github.io/ecometrica-pwa/",title="EcoMétrica 3.0: plataforma cienciométrica para revisões sistemáticas e análise da biodiversidade";return {abnt:`PINTO JÚNIOR, José Egberto Mesquita. ${title}. Versão 58. Mossoró: Universidade do Estado do Rio Grande do Norte, 2026. Software. Disponível em: ${url}. Acesso em: ${accessed}.`,apa:`Pinto Júnior, J. E. M. (2026). ${title} (Version 58) [Computer software]. Universidade do Estado do Rio Grande do Norte. ${url}`,vancouver:`Pinto Júnior JEM. ${title} [software]. Version 58. Mossoró: Universidade do Estado do Rio Grande do Norte; 2026 [cited ${accessed}]. Available from: ${url}`,chicago:`Pinto Júnior, José Egberto Mesquita. 2026. “${title}.” Version 58. Computer software. Mossoró: Universidade do Estado do Rio Grande do Norte. ${url}.`,bibtex:`@software{pinto_junior_ecometrica_2026,\n  author    = {Pinto Júnior, José Egberto Mesquita},\n  title     = {${title}},\n  version   = {58},\n  year      = {2026},\n  publisher = {Universidade do Estado do Rio Grande do Norte},\n  address   = {Mossoró, RN},\n  url       = {${url}},\n  urldate   = {${iso}}\n}`}}
function openCitationGenerator(){const citations=ecometricaCitations();document.body.insertAdjacentHTML("beforeend",`<div class="modal" id="citation-modal" role="dialog" aria-modal="true" aria-labelledby="citation-title"><section class="card citation-modal-card"><div class="citation-heading"><div><span class="eyebrow">Referência do software</span><h2 id="citation-title">Como citar a EcoMétrica</h2></div><button type="button" class="citation-close" id="close-citation" aria-label="Fechar">×</button></div><p class="muted">Escolha um dos estilos bibliográficos mais utilizados. A referência inclui autor, instituição, versão, endereço eletrônico e data de acesso.</p><div class="field"><label for="citation-style">Modelo de referência</label><select id="citation-style"><option value="abnt">ABNT NBR 6023</option><option value="apa">APA — 7ª edição</option><option value="vancouver">Vancouver</option><option value="chicago">Chicago — autor-data</option><option value="bibtex">BibTeX</option></select></div><div class="citation-preview" id="citation-preview" tabindex="0">${esc(citations.abnt)}</div><div class="actions"><button type="button" class="btn btn-outline" id="cancel-citation">Fechar</button><button type="button" class="btn btn-primary" id="copy-citation">Copiar referência</button></div><small class="muted citation-note">Confira as exigências específicas do periódico ou da instituição antes da submissão.</small></section></div>`);const modal=$("#citation-modal"),select=$("#citation-style"),preview=$("#citation-preview");const close=()=>modal.remove();select.addEventListener("change",()=>{preview.textContent=citations[select.value]});$("#close-citation").onclick=close;$("#cancel-citation").onclick=close;modal.addEventListener("click",event=>{if(event.target===modal)close()});document.addEventListener("keydown",function escapeCitation(event){if(event.key==="Escape"&&document.body.contains(modal)){close();document.removeEventListener("keydown",escapeCitation)}});$("#copy-citation").onclick=async()=>{try{await navigator.clipboard.writeText(preview.textContent);toast("Referência copiada.")}catch{const range=document.createRange();range.selectNodeContents(preview);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);toast("Referência selecionada. Use Copiar.")}};select.focus()}
function landing(){return `<div class="landing"><header class="public-nav"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><div class="actions"><button class="btn btn-outline help-trigger" type="button">? Ajuda</button><button class="btn btn-outline" data-go="login">Entrar</button><button class="btn btn-primary" data-go="register">Criar conta</button></div></header><main><section class="hero"><span class="eyebrow">PPGCN · UERN</span><h1>Plataforma Cienciométrica para Espécies Invasoras</h1><p>Ferramenta de revisão bibliográfica sistemática sobre espécies animais exóticas invasoras em ambientes aquáticos continentais da Caatinga, com foco no Rio Grande do Norte.</p><div class="actions"><button class="btn btn-primary" data-go="register">Começar revisão</button><button class="btn btn-outline" data-go="login">Já tenho acesso</button></div></section><section class="features">${[["Triagem Sistemática","Avalie títulos e resumos com critérios transparentes."],["Diagrama PRISMA","Acompanhe cada etapa da seleção de estudos."],["Análise Cienciométrica","Explore tendências, autores, periódicos e descritores."],["Mapa de Ocorrências","Consulte registros públicos de espécies via GBIF."]].map(x=>`<article class="feature"><span class="eyebrow">${x[0]}</span><b>${x[0]}</b><p>${x[1]}</p></article>`).join("")}</section></main>${appFooter()}</div>`}
function authPage(kind){const reg=kind==="register";return `<div class="auth-wrap"><form class="card auth-card" id="auth-form"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><h1>${reg?"Criar conta":"Bem-vindo de volta"}</h1><p class="muted">${reg?"Cadastre-se para iniciar sua revisão.":"Entre com sua conta segura."}</p><button type="button" class="btn btn-google" id="google-login"><span class="google-mark" aria-hidden="true">G</span>Continuar com Google</button><div class="auth-divider"><span>ou use seu e-mail</span></div>${reg?`<div class="field"><label>Nome</label><input name="name" required autocomplete="name"></div>`:""}<div class="field"><label>E-mail</label><input name="email" type="email" required autocomplete="email"></div><div class="field"><label>Senha</label><input name="password" type="password" minlength="8" required autocomplete="${reg?"new-password":"current-password"}"></div>${reg?`<div class="field"><label>Instituição</label><input name="institution" value="PPGCN/UERN" autocomplete="organization"></div>`:""}<button type="submit" class="btn btn-primary" style="width:100%">${reg?"Criar conta":"Entrar"}</button><p class="auth-switch">${reg?`Já possui uma conta? <a href="#/login">Entrar</a>`:`Ainda não possui uma conta? <a href="#/register">Criar conta</a>`}</p><button type="button" class="btn btn-outline" style="width:100%;margin-top:8px" data-go="home">Voltar</button></form></div>`}

function activeProject(){return cloudProjects.find(p=>p.id===activeProjectId)||null}
function shell(content){const active=activeNavKey(),project=activeProject(),context=project?`${esc(project.title)} · ${project.start_year}–${project.end_year}`:"Nenhum projeto ativo";return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><nav>${nav.filter(x=>x[0]!=="admin"||state.user.role==="admin").map(([p,l,i])=>`<a href="#/${p}" class="nav-link ${active===p?"active":""}" ${active===p?'aria-current="page"':""}><span>${i}</span> ${l}</a>`).join("")}</nav><div class="sidebar-foot">PPGCN/UERN<br>${project?`Projeto ativo: ${esc(project.title)}`:"Selecione um projeto"}<br><small>Protocolos sincronizados</small></div></aside><section class="app-main"><header class="topbar"><button class="menu-toggle" id="menu-toggle" aria-label="Abrir menu">☰</button><div class="topbar-context"><small>Projeto ativo</small><span>${context}</span></div><div class="user-chip"><button class="topbar-icon help-trigger" type="button" aria-label="Abrir ajuda" title="Ajuda">?</button><span class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span><span class="user-text"><b>${esc(state.user.name)}</b><small>${state.user.role==="admin"?"Administrador":"Pesquisador"}</small></span><button class="topbar-exit" id="logout" type="button">Sair</button></div></header><main class="content">${analysisFlow(active)}${content}</main>${appFooter()}</section></div>`}
function head(title,desc,actions=""){return `<header class="page-head"><div class="toolbar" style="justify-content:space-between"><div><h1>${title}</h1><p>${desc}</p></div>${actions}</div></header>`}
function empty(title,text,button=""){return `<div class="card empty"><h2>${title}</h2><p class="muted">${text}</p>${button}</div>`}

function dashboard(){const sessions=mine(state.sessions),articles=mine(state.articles),decisions=mine(state.screeningDecisions),occ=mine(state.occurrences),project=activeProject();const screened=decisions.filter(x=>x.decision!=="pending").length,total=decisions.length,progress=total?Math.round(screened/total*100):0,strategies=project?cloudStrategies.filter(x=>x.project_id===project.id).length:0;return `${head("Dashboard","Visão geral da revisão sistemática e de seu protocolo de pesquisa.")} ${project?`<section class="card project-context"><div><span class="eyebrow">Projeto ativo</span><h2>${esc(project.title)}</h2><p>${esc(project.research_question||"Questão de pesquisa ainda não informada.")}</p></div><div class="project-context-actions"><span class="badge green">${project.start_year}–${project.end_year}</span><button class="btn btn-outline btn-sm" data-go="projects">Ver protocolo</button></div></section>`:`<section class="notice project-empty"><b>Comece pelo protocolo da pesquisa.</b> Crie um projeto para registrar objetivos, critérios e versões das buscas. <button class="btn btn-primary btn-sm" data-go="projects">Criar projeto</button></section>`}<section class="grid metrics"><article class="card metric"><small>Estratégias salvas</small><div class="value">${strategies}</div></article><article class="card metric"><small>Artigos no corpus</small><div class="value">${articles.filter(x=>!x.isDuplicate).length}</div></article><article class="card metric"><small>Artigos triados</small><div class="value">${screened}</div></article><article class="card metric"><small>Ocorrências GBIF</small><div class="value">${occ.length}</div></article></section><section class="grid two-col" style="margin-top:16px"><article class="card"><h2>Progresso da triagem</h2><div class="progress"><span style="width:${progress}%"></span></div><p><b>${progress}%</b> · ${screened} de ${total||0} registros avaliados</p>${sessions.length?`<button class="btn btn-primary" data-go="sessions">Ver sessões</button>`:`<div class="notice">Crie sua primeira sessão importando um corpus bibliográfico.</div><button class="btn btn-primary" data-go="corpus" style="margin-top:12px">Importar corpus</button>`}</article><article class="card"><h2>Atividades recentes</h2>${mine(state.activities).slice(0,6).map(a=>`<p><b>${esc(a.description)}</b><br><small class="muted">${new Date(a.createdAt).toLocaleString("pt-BR")}</small></p>`).join("")||`<p class="muted">Nenhuma atividade registrada.</p>`}</article></section>`}

async function loadCloudResearchData(){
 if(!state.user){cloudProjects=[];cloudStrategies=[];cloudExecutions=[];activeProjectId="";return}
 const [projectsResult,strategiesResult,executionsResult]=await Promise.all([
  supabaseClient.from("research_projects").select("*").order("updated_at",{ascending:false}),
  supabaseClient.from("search_strategies").select("*").order("created_at",{ascending:false}),
  supabaseClient.from("search_executions").select("*").order("executed_at",{ascending:false})
 ]);
 const error=projectsResult.error||strategiesResult.error||executionsResult.error;if(error)throw error;
 cloudProjects=projectsResult.data||[];cloudStrategies=strategiesResult.data||[];cloudExecutions=executionsResult.data||[];
 if(!cloudProjects.some(p=>p.id===activeProjectId))activeProjectId=cloudProjects[0]?.id||"";
 if(activeProjectId)localStorage.setItem(ACTIVE_PROJECT_KEY,activeProjectId);else localStorage.removeItem(ACTIVE_PROJECT_KEY)
}
function lines(value){return Array.isArray(value)?value.join("\n"):""}
function dbChecks(selected=[]){return Object.entries(databases).map(([id,d])=>`<label class="protocol-check"><input type="checkbox" name="project_db" value="${id}" ${selected.includes(id)?"checked":""}> <span><b>${d[0]}</b><small>${d[4]}</small></span></label>`).join("")}
function projectsPage(){
 const current=creatingProject?null:activeProject(),strategies=current?cloudStrategies.filter(x=>x.project_id===current.id):[],executions=current?cloudExecutions.filter(x=>x.project_id===current.id):[];
 const projectList=cloudProjects.map(p=>`<button type="button" class="project-list-item ${p.id===activeProjectId&&!creatingProject?"active":""}" data-project-id="${p.id}"><b>${esc(p.title)}</b><small>${p.start_year}–${p.end_year} · ${p.status==="active"?"Ativo":p.status==="draft"?"Rascunho":"Arquivado"}</small></button>`).join("")||`<p class="muted">Nenhum projeto cadastrado.</p>`;
 const history=strategies.map(s=>{const runs=executions.filter(x=>x.strategy_id===s.id);return `<article class="card strategy-history"><div class="toolbar"><div><span class="eyebrow">Versão ${s.version}</span><h3>${esc(s.title)}</h3><small class="muted">${new Date(s.created_at).toLocaleString("pt-BR")} · ${(s.selected_databases||[]).map(id=>databases[id]?.[0]||id).join(", ")}</small></div></div><p>${esc(s.notes||"Sem observações.")}</p><details><summary>Ver strings registradas</summary>${Object.entries(s.generated_queries||{}).map(([id,q])=>`<h4>${esc(databases[id]?.[0]||id)}</h4><pre class="saved-query">${esc(q)}</pre>`).join("")}</details><form class="execution-form" data-strategy-id="${s.id}"><div class="field"><label>Base consultada</label><select name="database_id">${(s.selected_databases||[]).map(id=>`<option value="${id}">${esc(databases[id]?.[0]||id)}</option>`).join("")}</select></div><div class="field"><label>Resultados encontrados</label><input type="number" name="result_count" min="0" placeholder="Ex.: 248"></div><div class="field"><label>Observação</label><input name="notes" placeholder="Data, filtros ou ajustes realizados"></div><button class="btn btn-outline btn-sm" type="submit">Registrar execução</button></form>${runs.length?`<div class="run-list">${runs.map(r=>`<small><b>${esc(databases[r.database_id]?.[0]||r.database_id)}</b> · ${r.result_count??"quantidade não informada"} · ${new Date(r.executed_at).toLocaleString("pt-BR")}${r.notes?` · ${esc(r.notes)}`:""}</small>`).join("")}</div>`:""}</article>`}).join("");
 return `${head("Projetos e Protocolo","Registre o planejamento metodológico e preserve o histórico reproduzível de cada busca.",'<button class="btn btn-primary" id="new-project">Novo projeto</button>')}<section class="protocol-layout"><aside class="card project-list"><h2>Meus projetos</h2>${projectList}</aside><div><form id="project-form" class="card protocol-form"><input type="hidden" name="id" value="${current?.id||""}"><div class="toolbar"><div><span class="eyebrow">${current?"Protocolo ativo":"Novo protocolo"}</span><h2>${current?esc(current.title):"Criar projeto de pesquisa"}</h2></div><button class="btn btn-primary" type="submit">Salvar protocolo</button></div><div class="field"><label>Título do projeto *</label><input name="title" required value="${esc(current?.title||"")}" placeholder="Ex.: Espécies exóticas invasoras em ambientes aquáticos"></div><div class="field"><label>Questão de pesquisa</label><textarea name="research_question" rows="3" placeholder="Qual pergunta orientará a revisão?">${esc(current?.research_question||"")}</textarea></div><div class="field"><label>Objetivo geral</label><textarea name="general_objective" rows="3">${esc(current?.general_objective||"")}</textarea></div><div class="field"><label>Objetivos específicos</label><textarea name="specific_objectives" rows="5" placeholder="Informe um objetivo por linha">${esc(lines(current?.specific_objectives))}</textarea></div><div class="grid two-col"><div class="field"><label>Ano inicial</label><input type="number" name="start_year" min="1900" max="2100" value="${current?.start_year||2004}" required></div><div class="field"><label>Ano final</label><input type="number" name="end_year" min="1900" max="2100" value="${current?.end_year||2025}" required></div></div><div class="grid two-col"><div class="field"><label>Critérios de inclusão</label><textarea name="inclusion_criteria" rows="6">${esc(current?.inclusion_criteria||"")}</textarea></div><div class="field"><label>Critérios de exclusão</label><textarea name="exclusion_criteria" rows="6">${esc(current?.exclusion_criteria||"")}</textarea></div></div><fieldset><legend>Bases de dados previstas</legend><div class="protocol-databases">${dbChecks(current?.selected_databases||[])}</div></fieldset><div class="grid two-col"><div class="field"><label>Instituição</label><input name="institution" value="${esc(current?.institution||state.user.institution||"PPGCN/UERN")}"></div><div class="field"><label>Status</label><select name="status"><option value="active" ${current?.status==="active"?"selected":""}>Ativo</option><option value="draft" ${current?.status==="draft"?"selected":""}>Rascunho</option><option value="archived" ${current?.status==="archived"?"selected":""}>Arquivado</option></select></div></div></form>${current?`<section class="protocol-history"><div class="toolbar"><div><h2>Histórico de buscas</h2><p class="muted">Versões imutáveis das estratégias e registros das consultas realizadas.</p></div><button class="btn btn-outline" data-go="search">Criar nova estratégia</button></div>${history||empty("Nenhuma estratégia salva","Gere uma string no Construtor de Busca e salve-a neste projeto.")}</section>`:""}</div></section>`
}
async function saveProject(form){const f=new FormData(form),id=String(f.get("id")||""),start=Number(f.get("start_year")),end=Number(f.get("end_year"));if(start>end)return toast("O ano inicial deve ser anterior ao ano final.");const payload={owner_id:state.user.id,title:String(f.get("title")).trim(),research_question:String(f.get("research_question")||"").trim(),general_objective:String(f.get("general_objective")||"").trim(),specific_objectives:String(f.get("specific_objectives")||"").split(/\n+/).map(x=>x.trim()).filter(Boolean),start_year:start,end_year:end,inclusion_criteria:String(f.get("inclusion_criteria")||"").trim(),exclusion_criteria:String(f.get("exclusion_criteria")||"").trim(),selected_databases:f.getAll("project_db"),institution:String(f.get("institution")||"").trim(),status:f.get("status"),updated_at:now()};const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent="Salvando…";const result=id?await supabaseClient.from("research_projects").update(payload).eq("id",id).select().single():await supabaseClient.from("research_projects").insert(payload).select().single();if(result.error){button.disabled=false;button.textContent="Salvar protocolo";return toast(`Não foi possível salvar: ${result.error.message}`)}activeProjectId=result.data.id;creatingProject=false;localStorage.setItem(ACTIVE_PROJECT_KEY,activeProjectId);await loadCloudResearchData();toast("Protocolo salvo e sincronizado.");render()}
async function saveExecution(form){const f=new FormData(form),project=activeProject();if(!project)return;const count=String(f.get("result_count")||"").trim();const {error}=await supabaseClient.from("search_executions").insert({project_id:project.id,strategy_id:form.dataset.strategyId,owner_id:state.user.id,database_id:f.get("database_id"),result_count:count===""?null:Number(count),notes:String(f.get("notes")||"").trim(),executed_at:now()});if(error)return toast(`Não foi possível registrar: ${error.message}`);await loadCloudResearchData();toast("Execução registrada no histórico.");render()}

