function articleTable(arts){return `<div class="table-wrap"><table><thead><tr><th>Título</th><th>Autores</th><th>Ano</th><th>Fonte</th><th>Status</th></tr></thead><tbody>${arts.map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.authors||"—")}</td><td>${a.year||"—"}</td><td>${esc(a.source||"—")}</td><td>${a.isDuplicate?`<span class="badge red">Removido como duplicata</span>`:`<span class="badge green">Mantido</span>`}</td></tr>`).join("")}</tbody></table></div>`}
function decideDuplicate(auditId,decision){const audit=state.deduplicationAudits.find(x=>x.id===auditId);if(!audit||audit.decision!=="pending")return;const note=$(`[data-audit-note="${auditId}"]`)?.value.trim()||"";audit.decision=decision;audit.note=note;audit.reviewerId=state.user.id;audit.reviewerName=state.user.name;audit.decidedAt=now();const duplicate=state.articles.find(a=>a.id===audit.duplicateArticleId);if(duplicate){duplicate.isDuplicate=decision==="remove";duplicate.deduplicationReason=decision==="remove"?audit.reason:""}const session=state.sessions.find(s=>s.id===audit.sessionId),audits=state.deduplicationAudits.filter(x=>x.sessionId===audit.sessionId);session.duplicateCount=audits.filter(x=>x.decision==="remove").length;session.duplicateCandidateCount=audits.length;session.deduplicationConfirmed=false;save();activity("dedup_decision",`${decision==="remove"?"Duplicata confirmada":"Registros mantidos"}: ${duplicate?.title||"registro"}`,session.name);render()}
function exportDedupAudit(sessionId){const session=state.sessions.find(s=>s.id===sessionId),audits=ensureDedupAudits(sessionId),header=["audit_id","sessao","regra","justificativa","confianca","decisao","titulo_principal","doi_principal","titulo_comparado","doi_comparado","revisor","data_decisao","observacao"],rows=audits.map(a=>{const p=state.articles.find(x=>x.id===a.primaryArticleId)||{},d=state.articles.find(x=>x.id===a.duplicateArticleId)||{};return [a.id,session.name,a.rule,a.reason,a.confidence,a.decision,p.title,p.doi,d.title,d.doi,a.reviewerName,a.decidedAt,a.note]});download(`auditoria-deduplicacao-${norm(session.name).replaceAll(" ","-")||"sessao"}.csv`,[header,...rows].map(row=>row.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n"),"text/csv")}

function splitTerms(value,kind){const separator=kind==="authors"?/;|\sand\s/i:/[;,|]/;return [...new Set(String(value||"").split(separator).map(x=>x.trim()).filter(Boolean).map(x=>kind==="keywords"?x.toLowerCase():x))]}
function analysisArticles(sessionId,scope="deduplicated"){const deduplicated=state.articles.filter(a=>a.sessionId===sessionId&&!a.isDuplicate),screening=mine(state.screeningSessions).filter(s=>s.analysisSessionId===sessionId).at(-1);if(scope==="deduplicated"||!screening)return {arts:scope==="deduplicated"?deduplicated:[],screening};const acceptedIds=new Set(state.screeningDecisions.filter(d=>d.screeningSessionId===screening.id&&d.decision==="include").map(d=>d.articleId));if(scope==="screened")return {arts:deduplicated.filter(a=>acceptedIds.has(a.id)),screening};const finalIds=new Set(state.eligibilityDecisions.filter(d=>d.screeningSessionId===screening.id&&d.decision==="include").map(d=>d.articleId));return {arts:deduplicated.filter(a=>finalIds.has(a.id)),screening}}
function statsFor(sessionId,scope="deduplicated"){const {arts,screening}=analysisArticles(sessionId,scope),count=(map,key)=>{if(key)map[key]=(map[key]||0)+1};let years={},journals={},authors={},keywords={},sources={};arts.forEach(a=>{count(years,a.year);count(journals,a.journal||a.source);count(sources,a.source);splitTerms(a.authors,"authors").forEach(x=>count(authors,x));splitTerms(a.keywords,"keywords").forEach(x=>count(keywords,x))});const top=(o,n=Number.MAX_SAFE_INTEGER)=>Object.entries(o).sort((a,b)=>b[1]-a[1]||String(a[0]).localeCompare(String(b[0]))).slice(0,n);return {arts,screening,years:top(years).sort((a,b)=>+a[0]-+b[0]),journals:top(journals),authors:top(authors),keywords:top(keywords),sources:top(sources,10),citations:arts.reduce((s,a)=>s+(+a.citationCount||0),0)}}
function bars(data){const max=Math.max(1,...data.map(x=>x[1]));return `<div class="bars">${data.map(([l,v])=>`<div class="bar-row"><span title="${esc(l)}">${esc(l||"Não informado")}</span><div class="bar-track"><span style="width:${v/max*100}%"></span></div><b>${v}</b></div>`).join("")||`<p class="muted">Sem dados.</p>`}</div>`}
function annualChart(years){if(!years.length)return `<p class="muted">Sem anos válidos para representar.</p>`;const max=Math.max(...years.map(x=>x[1]),1);return `<div class="annual-chart" role="img" aria-label="Produção científica anual">${years.map(([year,count])=>`<div class="annual-column" title="${year}: ${count} publicação(ões)"><b>${count}</b><span style="height:${Math.max(8,count/max*150)}px"></span><small>${esc(year)}</small></div>`).join("")}</div>`}
function networkData(arts,kind,limit=18){const counts={},pairs={};arts.forEach(article=>{const terms=splitTerms(article[kind],kind);terms.forEach(t=>counts[t]=(counts[t]||0)+1);for(let i=0;i<terms.length;i++)for(let j=i+1;j<terms.length;j++){const key=[terms[i],terms[j]].sort().join("\u0001");pairs[key]=(pairs[key]||0)+1}});const labels=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,limit).map(x=>x[0]),allowed=new Set(labels),nodes=labels.map((label,i)=>{const angle=Math.PI*2*i/Math.max(labels.length,1)-Math.PI/2,ring=i%3,rx=260-ring*34,ry=165-ring*20;return {label,count:counts[label],x:450+Math.cos(angle)*rx,y:235+Math.sin(angle)*ry}}),byLabel=Object.fromEntries(nodes.map(n=>[n.label,n])),edges=Object.entries(pairs).map(([key,weight])=>{const [a,b]=key.split("\u0001");return {a,b,weight}}).filter(e=>allowed.has(e.a)&&allowed.has(e.b)).sort((a,b)=>b.weight-a.weight).slice(0,45);return {nodes,edges,byLabel}}
function networkGraph(arts,kind,title){const net=networkData(arts,kind);if(net.nodes.length<2)return `<div class="network-empty">Metadados insuficientes para formar esta rede.</div>`;const max=Math.max(...net.nodes.map(n=>n.count),1),edgeMax=Math.max(...net.edges.map(e=>e.weight),1),nodeIndex=Object.fromEntries(net.nodes.map((n,i)=>[n.label,i]));return `<div class="network-wrap"><svg class="science-network" viewBox="0 0 900 470" role="img" aria-label="${esc(title)}"><g class="network-edges">${net.edges.map(e=>{const a=net.byLabel[e.a],b=net.byLabel[e.b];return `<line class="network-edge" data-a="${nodeIndex[e.a]}" data-b="${nodeIndex[e.b]}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" style="stroke-width:${.7+e.weight/edgeMax*3}"/>`}).join("")}</g><g class="network-nodes">${net.nodes.map((n,i)=>{const radius=10+n.count/max*17,color=["#166534","#0f766e","#2563eb","#b45309","#7c3aed"][i%5];return `<g class="network-node" data-node="${i}" data-label="${esc(n.label)}" data-count="${n.count}" tabindex="0" role="button" aria-label="${esc(n.label)}, frequência ${n.count}"><circle cx="${n.x}" cy="${n.y}" r="${radius}" fill="${color}"><title>${esc(n.label)} — ${n.count}</title></circle><text x="${n.x}" y="${n.y+radius+13}" text-anchor="middle">${esc(n.label.length>24?n.label.slice(0,22)+"…":n.label)}</text></g>`}).join("")}</g></svg><div class="network-focus-label" aria-live="polite">Passe o mouse sobre um nó para destacar suas conexões.</div><div class="network-legend"><span>O tamanho do nó representa a frequência.</span><span>A espessura da linha representa a força da relação.</span></div></div>`}

function bindNetworkInteractions(){ $$(".science-network").forEach(svg=>{if(svg.dataset.interactive==="true")return;svg.dataset.interactive="true";const nodes=$$(".network-node",svg),edges=$$(".network-edge",svg),label=svg.nextElementSibling;const clear=()=>{svg.classList.remove("is-focused");nodes.forEach(n=>n.classList.remove("is-active","is-neighbor"));edges.forEach(e=>e.classList.remove("is-active"));if(label)label.textContent="Passe o mouse sobre um nó para destacar suas conexões."};const focus=node=>{const id=node.dataset.node,neighbors=new Set();svg.classList.add("is-focused");edges.forEach(edge=>{const active=edge.dataset.a===id||edge.dataset.b===id;edge.classList.toggle("is-active",active);if(active)neighbors.add(edge.dataset.a===id?edge.dataset.b:edge.dataset.a)});nodes.forEach(n=>{n.classList.toggle("is-active",n.dataset.node===id);n.classList.toggle("is-neighbor",neighbors.has(n.dataset.node))});if(label)label.innerHTML=`<b>${esc(node.dataset.label)}</b> · frequência ${node.dataset.count} · ${neighbors.size} conexão(ões)`};nodes.forEach(node=>{node.addEventListener("pointerenter",()=>focus(node));node.addEventListener("pointerleave",clear);node.addEventListener("focus",()=>focus(node));node.addEventListener("blur",clear);node.addEventListener("click",()=>focus(node));node.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();focus(node)}})})})}
function bradfordAnalysis(journals){const rows=journals.filter(x=>x[0]),total=rows.reduce((sum,x)=>sum+x[1],0),target=total/3;let cumulative=0,zone=1;const classified=rows.map(([journal,count])=>{cumulative+=count;const row={journal,count,cumulative,zone};if(cumulative>=target*zone&&zone<3)zone++;return row}),zones=[1,2,3].map(z=>{const group=classified.filter(r=>r.zone===z);return {zone:z,journals:group.length,articles:group.reduce((s,r)=>s+r.count,0)}});return {total,classified,zones}}
function bradfordView(journals){const b=bradfordAnalysis(journals);if(!b.total)return `<p class="muted">Os periódicos não foram informados nos arquivos importados.</p>`;return `<div class="bradford-zones">${b.zones.map((z,i)=>`<div class="bradford-zone zone-${z.zone}"><span>Zona ${z.zone}${i===0?" · núcleo":""}</span><b>${z.journals} periódico(s)</b><small>${z.articles} artigo(s)</small></div>`).join("")}</div><div class="table-wrap bradford-table"><table><thead><tr><th>Posição</th><th>Periódico</th><th>Artigos</th><th>Acumulado</th><th>Zona</th></tr></thead><tbody>${b.classified.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.journal)}</td><td>${r.count}</td><td>${r.cumulative}</td><td><span class="badge ${r.zone===1?"green":""}">Zona ${r.zone}</span></td></tr>`).join("")}</tbody></table></div>`}
function resultsPage(){const sessions=mine(state.sessions),params=new URLSearchParams(location.hash.split("?")[1]||""),requested=params.get("session"),sid=sessions.some(s=>s.id===requested)?requested:sessions.at(-1)?.id,scope=["deduplicated","screened","final"].includes(params.get("scope"))?params.get("scope"):"deduplicated",st=statsFor(sid,scope),scopeLabels={deduplicated:"Corpus deduplicado",screened:"Aprovados na triagem",final:"Incluídos após elegibilidade"},scopeDescriptions={deduplicated:"todos os registros mantidos após a auditoria de duplicatas",screened:"somente os artigos incluídos na triagem de títulos e resumos",final:"somente os estudos incluídos após a avaliação do texto completo"},missingFlow=scope!=="deduplicated"&&!st.screening;return `${head("Análise Cienciométrica",`Produção, desempenho e redes do universo: ${scopeLabels[scope]}.`,`<div class="actions"><button class="btn btn-outline" data-go="vosviewer">Exportar para VOSviewer</button><button id="print-results" class="btn btn-outline">Imprimir / PDF</button></div>`)}<section class="card analysis-filters"><div class="grid two-col"><div class="field"><label>Sessão analisada</label><select id="result-session">${sessions.map(s=>`<option value="${s.id}" ${s.id===sid?"selected":""}>${esc(s.name)} · ${s.articleCount-(s.duplicateCount||0)} registro(s)</option>`).join("")}</select></div><div class="field"><label>Universo da análise</label><select id="analysis-scope"><option value="deduplicated" ${scope==="deduplicated"?"selected":""}>Corpus deduplicado</option><option value="screened" ${scope==="screened"?"selected":""}>Artigos aprovados na triagem</option><option value="final" ${scope==="final"?"selected":""}>Estudos incluídos após a elegibilidade</option></select></div></div><div class="notice ${missingFlow?"danger-note":""}"><b>Escopo atual:</b> ${scopeDescriptions[scope]}.${st.screening&&scope!=="deduplicated"?` Triagem vinculada: “${esc(st.screening.name)}”.`:""}${missingFlow?" Esta sessão ainda não possui uma triagem vinculada.":""} As análises dependem da completude dos campos importados.</div></section><section class="grid metrics" style="margin-top:16px"><article class="card metric"><small>Artigos analisados</small><div class="value">${st.arts.length}</div></article><article class="card metric"><small>Citações informadas</small><div class="value">${st.citations}</div></article><article class="card metric"><small>Autores identificados</small><div class="value">${st.authors.length}</div></article><article class="card metric"><small>Palavras-chave</small><div class="value">${st.keywords.length}</div></article></section>${st.arts.length?`<section class="analytics-section"><div class="analytics-title"><span>1</span><div><h2>Produção científica anual</h2><p>Evolução do volume de publicações ao longo do tempo.</p></div></div><article class="card">${annualChart(st.years)}</article></section><section class="analytics-section"><div class="analytics-title"><span>2</span><div><h2>Desempenho de periódicos e autores</h2><p>Fontes e pesquisadores com maior produtividade no universo selecionado.</p></div></div><div class="grid two-col"><article class="card"><h3>Periódicos mais produtivos</h3>${bars(st.journals.slice(0,12))}</article><article class="card"><h3>Autores mais produtivos</h3>${bars(st.authors.slice(0,12))}</article></div></section><section class="analytics-section"><div class="analytics-title"><span>3</span><div><h2>Palavras-chave mais frequentes</h2><p>Descritores dominantes nos documentos selecionados.</p></div></div><article class="card">${bars(st.keywords.slice(0,20))}</article></section><section class="analytics-section"><div class="analytics-title"><span>4</span><div><h2>Rede de coautoria</h2><p>Colaborações formadas por autores presentes no mesmo artigo.</p></div></div><article class="card network-card">${networkGraph(st.arts,"authors","Rede de coautoria")}</article></section><section class="analytics-section"><div class="analytics-title"><span>5</span><div><h2>Rede de coocorrência de palavras-chave</h2><p>Proximidade temática calculada pela presença conjunta de termos.</p></div></div><article class="card network-card">${networkGraph(st.arts,"keywords","Rede de coocorrência de palavras-chave")}</article></section><section class="analytics-section"><div class="analytics-title"><span>6</span><div><h2>Lei de Bradford</h2><p>Distribuição dos periódicos em três zonas com aproximadamente um terço dos artigos cada.</p></div></div><article class="card">${bradfordView(st.journals)}</article></section>`:`<div class="card empty analysis-empty"><h2>Nenhum artigo neste universo</h2><p>${scope==="screened"?"A triagem ainda não possui artigos incluídos para esta sessão.":scope==="final"?"A elegibilidade ainda não possui estudos incluídos no corpus final.":"A sessão não possui registros deduplicados."}</p></div>`}`}

function screeningPage(){const sessions=mine(state.sessions),ss=mine(state.screeningSessions);return `${head("Triagem de Artigos","Avalie títulos e resumos com critérios explícitos.",`<button id="new-screening" class="btn btn-primary">Nova triagem</button>`)}${ss.length?`<div class="grid">${ss.map(x=>{const ds=state.screeningDecisions.filter(d=>d.screeningSessionId===x.id),done=ds.filter(d=>d.decision!=="pending").length;return `<article class="card"><h2>${esc(x.name)}</h2><p>${done} de ${ds.length} avaliados</p><div class="progress"><span style="width:${ds.length?done/ds.length*100:0}%"></span></div><button class="btn btn-primary" data-go="screen/${x.id}" style="margin-top:12px">Continuar</button></article>`}).join("")}</div>`:empty("Nenhuma triagem","Crie uma triagem a partir de uma sessão deduplicada.")}`}
function createScreening(){const sessions=mine(state.sessions).filter(s=>s.deduplicationConfirmed);if(!sessions.length)return toast("Conclua a auditoria de deduplicação antes de iniciar a triagem.");document.body.insertAdjacentHTML("beforeend",`<div class="modal" id="screening-modal"><form class="card modal-card" id="screening-form"><h2>Iniciar nova triagem</h2><p class="muted">Escolha uma sessão com deduplicação concluída. Os registros mantidos serão preparados para avaliação.</p><div class="field"><label>Sessão de análise</label><select name="session_id" required>${sessions.map((s,i)=>`<option value="${s.id}">${esc(s.name)} · ${new Date(s.createdAt).toLocaleString("pt-BR")} · ${s.articleCount-(s.duplicateCount||0)} registros</option>`).join("")}</select></div><div class="field"><label>Nome da triagem</label><input name="name" required value="Triagem ${esc(sessions[0].name)}" placeholder="Ex.: Triagem por título e resumo"></div><div class="actions"><button type="button" class="btn btn-outline" id="cancel-screening">Cancelar</button><button type="submit" class="btn btn-primary">Criar e abrir triagem</button></div></form></div>`);$("#cancel-screening").onclick=()=>$("#screening-modal").remove();$("#screening-form").elements.session_id.addEventListener("change",e=>{const s=sessions.find(x=>x.id===e.target.value);$("#screening-form").elements.name.value=`Triagem ${s.name}`});$("#screening-form").onsubmit=e=>{e.preventDefault();startScreening(e.currentTarget)}}
function startScreening(form){const f=new FormData(form),s=state.sessions.find(x=>x.id===f.get("session_id"));if(!s||!s.deduplicationConfirmed)return toast("Selecione uma sessão com deduplicação concluída.");const articles=state.articles.filter(a=>a.sessionId===s.id&&!a.isDuplicate);if(!articles.length)return toast("A sessão não possui registros mantidos para triagem.");const name=String(f.get("name")||"").trim(),ss={id:uid(),owner:state.user.id,name,analysisSessionId:s.id,status:"in_progress",createdAt:now()};state.screeningSessions.push(ss);articles.forEach(a=>state.screeningDecisions.push({id:uid(),owner:state.user.id,screeningSessionId:ss.id,articleId:a.id,decision:"pending",reason:"",createdAt:now()}));save();activity("screening_started",`Triagem “${name}” iniciada com ${articles.length} registros`,name);$("#screening-modal")?.remove();go(`screen/${ss.id}`)}
function screenDetail(id){const ss=state.screeningSessions.find(x=>x.id===id),ds=state.screeningDecisions.filter(x=>x.screeningSessionId===id),idx=Math.max(0,ds.findIndex(x=>x.decision==="pending")),d=ds[idx],a=d&&state.articles.find(x=>x.id===d.articleId),done=ds.filter(x=>x.decision!=="pending").length,included=ds.filter(x=>x.decision==="include").length;if(!ss)return empty("Triagem não encontrada","");if(!a)return `${head(esc(ss.name),"Triagem concluída")}<div class="card empty"><h2>Todos os artigos foram avaliados</h2><p>${included} artigo(s) foram encaminhados diretamente para a elegibilidade.</p><button class="btn btn-primary" data-go="eligibility/${ss.id}">Avaliar elegibilidade</button></div>`;return `${head(esc(ss.name),`${done} de ${ds.length} avaliados`)}<div class="progress"><span style="width:${ds.length?done/ds.length*100:0}%"></span></div><div class="notice" style="margin-top:16px"><b>Fluxo integrado:</b> ao incluir um artigo, ele é encaminhado automaticamente para a etapa de Elegibilidade.</div><section class="grid two-col" style="margin-top:16px"><article class="card article-focus"><span class="badge">${idx+1} de ${ds.length}</span><h2>${esc(a.title)}</h2><p class="muted">${esc(a.authors||"Autores não informados")} · ${a.year||"Ano não informado"}</p><div class="abstract">${esc(a.abstract||"Resumo não disponível. A decisão deve considerar essa limitação.")}</div><div class="field"><label>Motivo ou observação</label><textarea id="decision-reason" placeholder="Obrigatório para exclusão"></textarea></div><div class="decision-actions"><button class="btn btn-primary decision" data-decision="include">Incluir e enviar à elegibilidade</button><button class="btn btn-danger decision" data-decision="exclude">Excluir</button><button class="btn btn-outline decision" data-decision="pending">Manter pendente</button></div></article><aside class="card"><h3>Critérios de inclusão</h3><ul><li>Espécies animais exóticas invasoras</li><li>Ambientes aquáticos continentais</li><li>Caatinga, semiárido nordestino ou RN</li><li>Período de 2004 a 2025</li><li>Artigo revisado por pares</li></ul><h3>Critérios de exclusão</h3><ul><li>Exclusivamente marinho ou estuarino</li><li>Exclusivamente vegetal</li><li>Sem relação com águas continentais</li><li>Fora da área geográfica</li></ul></aside></section>`}
function ensureEligibilityDecision(screeningDecision){let eligibility=state.eligibilityDecisions.find(e=>e.screeningSessionId===screeningDecision.screeningSessionId&&e.articleId===screeningDecision.articleId);if(!eligibility){eligibility={id:uid(),owner:state.user.id,screeningSessionId:screeningDecision.screeningSessionId,articleId:screeningDecision.articleId,decision:"pending",reason:"",createdAt:now()};state.eligibilityDecisions.push(eligibility)}return eligibility}
function syncEligibility(screeningId){const included=mine(state.screeningDecisions).filter(d=>d.screeningSessionId===screeningId&&d.decision==="include");let changed=false;included.forEach(d=>{if(!state.eligibilityDecisions.some(e=>e.screeningSessionId===d.screeningSessionId&&e.articleId===d.articleId)){ensureEligibilityDecision(d);changed=true}});if(changed)save();return state.eligibilityDecisions.filter(e=>e.screeningSessionId===screeningId)}
function decide(screenId,decision){const d=state.screeningDecisions.find(x=>x.screeningSessionId===screenId&&x.decision==="pending");if(!d)return;const reason=$("#decision-reason").value.trim();if(decision==="exclude"&&!reason)return toast("Informe o motivo da exclusão.");d.decision=decision;d.reason=reason;d.screenedAt=now();if(decision==="include")ensureEligibilityDecision(d);save();activity("screening_decision",`${decision==="include"?"Artigo encaminhado à elegibilidade":"Artigo excluído na triagem"}: ${state.articles.find(a=>a.id===d.articleId)?.title||"registro"}`,state.screeningSessions.find(s=>s.id===screenId)?.name||"");render()}

function eligibilityPage(requestedId){const screenings=mine(state.screeningSessions).filter(s=>state.screeningDecisions.some(d=>d.screeningSessionId===s.id&&d.decision==="include")),selected=screenings.find(s=>s.id===requestedId)||screenings.at(-1);if(!selected)return `${head("Elegibilidade","Recebe automaticamente os artigos incluídos na triagem.")}${empty("Nenhum artigo encaminhado","Inclua pelo menos um artigo na Triagem para iniciar a avaliação de texto completo.")}`;const decisions=syncEligibility(selected.id),pending=decisions.filter(e=>e.decision==="pending"),included=decisions.filter(e=>e.decision==="include").length,excluded=decisions.filter(e=>e.decision==="exclude").length,done=included+excluded,e=pending[0],a=e&&state.articles.find(x=>x.id===e.articleId);return `${head("Elegibilidade",`Vinculada à triagem “${esc(selected.name)}”.`)}<section class="card"><div class="field"><label>Triagem de origem</label><select id="eligibility-session">${screenings.map(s=>`<option value="${s.id}" ${s.id===selected.id?"selected":""}>${esc(s.name)} · ${state.screeningDecisions.filter(d=>d.screeningSessionId===s.id&&d.decision==="include").length} encaminhado(s)</option>`).join("")}</select></div></section><section class="grid metrics" style="margin-top:16px"><article class="card metric"><small>Encaminhados pela triagem</small><div class="value">${decisions.length}</div></article><article class="card metric"><small>Avaliados em texto completo</small><div class="value">${done}</div></article><article class="card metric"><small>Incluídos no estudo</small><div class="value">${included}</div></article><article class="card metric"><small>Excluídos com justificativa</small><div class="value">${excluded}</div></article></section>${a?`<article class="card article-focus" style="margin-top:16px"><span class="badge">${pending.length} pendente(s)</span><h2>${esc(a.title)}</h2><p>${esc(a.authors||"")} · ${a.year||"—"}</p><div class="abstract">${esc(a.abstract||"Resumo não disponível. Consulte o texto completo antes da decisão final.")}</div>${a.doi?`<p><a href="https://doi.org/${encodeURIComponent(normalizeDOI(a.doi))}" target="_blank" rel="noopener">Abrir texto pelo DOI ↗</a></p>`:""}<div class="field"><label>Motivo ou observação da elegibilidade</label><textarea id="elig-reason" placeholder="Obrigatório para exclusão"></textarea></div><div class="decision-actions"><button class="btn btn-primary elig" data-decision="include">Incluir no estudo</button><button class="btn btn-danger elig" data-decision="exclude">Excluir após texto completo</button><button class="btn btn-outline elig" data-decision="pending">Manter pendente</button></div></article>`:`<div class="card empty" style="margin-top:16px"><h2>Elegibilidade concluída</h2><p>${included} estudo(s) incluído(s) e ${excluded} excluído(s) após avaliação do texto completo.</p><div class="actions"><button class="btn btn-primary" data-go="prisma">Ver diagrama PRISMA</button><button class="btn btn-outline" data-go="results">Ver resultados</button></div></div>`}`}
function decideEligibility(screeningId,decision){const e=mine(state.eligibilityDecisions).find(x=>x.screeningSessionId===screeningId&&x.decision==="pending");if(!e)return;const reason=$("#elig-reason")?.value.trim()||"";if(decision==="exclude"&&!reason)return toast("Informe o motivo da exclusão após avaliação do texto completo.");e.decision=decision;e.reason=reason;e.decidedAt=now();activity("eligibility_decision",`${decision==="include"?"Estudo incluído":"Artigo excluído após texto completo"}: ${state.articles.find(a=>a.id===e.articleId)?.title||"registro"}`,state.screeningSessions.find(s=>s.id===screeningId)?.name||"");save();render()}

function prismaReasons(decisions){const grouped={};decisions.forEach(d=>{const reason=String(d.reason||"Motivo não informado").trim();grouped[reason]=(grouped[reason]||0)+1});const rows=Object.entries(grouped).sort((a,b)=>b[1]-a[1]);return rows.length?`<ul class="prisma-reasons">${rows.map(([reason,count])=>`<li><span>${esc(reason)}</span><b>n = ${count}</b></li>`).join("")}</ul>`:`<p class="prisma-none">Nenhuma exclusão registrada.</p>`}
function prismaSources(sessionId){const grouped={};state.articles.filter(a=>a.sessionId===sessionId).forEach(a=>{const source=String(a.source||a._file||"Fonte não informada").trim();grouped[source]=(grouped[source]||0)+1});const rows=Object.entries(grouped).sort((a,b)=>b[1]-a[1]);return rows.length?rows.map(([source,count])=>`${esc(source)} (n = ${count})`).join("; "):"Fonte não informada"}
function loadPdfLibrary(src,test){if(test())return Promise.resolve();return new Promise((resolve,reject)=>{const existing=document.querySelector(`script[data-pdf-lib="${src}"]`);if(existing){existing.addEventListener("load",resolve,{once:true});existing.addEventListener("error",reject,{once:true});return}const script=document.createElement("script");script.src=src;script.dataset.pdfLib=src;script.onload=resolve;script.onerror=reject;document.head.appendChild(script)})}
async function exportPrismaPdf(){const button=$("#print-prisma"),flow=$(".prisma-flow"),note=$(".prisma-note");if(!flow)return toast("Diagrama PRISMA não encontrado.");button.disabled=true;button.textContent="Preparando PDF…";try{await Promise.all([loadPdfLibrary("https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js",()=>!!window.html2canvas),loadPdfLibrary("https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js",()=>!!window.jspdf?.jsPDF)]);if(!window.html2canvas||!window.jspdf?.jsPDF)throw new Error("Biblioteca de PDF indisponível");button.textContent="Gerando PDF…";const wrapper=document.createElement("div");wrapper.style.cssText="position:fixed;left:-20000px;top:0;width:1180px;padding:28px;background:#fff;color:#17201a;z-index:-1";wrapper.innerHTML=`<h1 style="font:700 30px Georgia,serif;margin:0 0 6px">Diagrama PRISMA 2020</h1><p style="margin:0 0 20px;color:#617066">${esc(mine(state.screeningSessions).at(-1)?.name||"Fluxo de seleção dos estudos")}</p>`;wrapper.append(flow.cloneNode(true),note.cloneNode(true));document.body.appendChild(wrapper);const canvas=await window.html2canvas(wrapper,{scale:2,backgroundColor:"#ffffff",useCORS:true,logging:false});wrapper.remove();const {jsPDF}=window.jspdf,pdf=new jsPDF({orientation:"landscape",unit:"mm",format:"a4",compress:true}),pageWidth=pdf.internal.pageSize.getWidth(),pageHeight=pdf.internal.pageSize.getHeight(),margin=8,imgWidth=pageWidth-margin*2,imgHeight=canvas.height*imgWidth/canvas.width,pageContent=pageHeight-margin*2,img=canvas.toDataURL("image/jpeg",.94);let offset=0,page=0;while(offset<imgHeight){if(page)pdf.addPage();pdf.addImage(img,"JPEG",margin,margin-offset,imgWidth,imgHeight,undefined,"FAST");offset+=pageContent;page++}pdf.save(`diagrama-prisma-2020-${new Date().toISOString().slice(0,10)}.pdf`);toast("PDF do PRISMA gerado com sucesso.")}catch(error){console.error("Falha ao gerar PDF do PRISMA",error);toast("Não foi possível gerar o PDF. Verifique a conexão e tente novamente.")}finally{button.disabled=false;button.textContent="Baixar PDF"}}
function prismaPage(){const ss=mine(state.screeningSessions).at(-1);if(!ss)return `${head("Diagrama PRISMA","Fluxo de seleção dos estudos.")}${empty("Sem sessão de triagem","Inicie uma triagem para gerar o diagrama.")}`;syncEligibility(ss.id);const ds=state.screeningDecisions.filter(d=>d.screeningSessionId===ss.id),eds=state.eligibilityDecisions.filter(e=>e.screeningSessionId===ss.id),session=state.sessions.find(s=>s.id===ss.analysisSessionId),identified=(session?.articleCount||ds.length),dups=session?.duplicateCount||0,screened=ds.filter(d=>d.decision!=="pending").length,screenPending=ds.filter(d=>d.decision==="pending").length,screenExcluded=ds.filter(d=>d.decision==="exclude"),forwarded=ds.filter(d=>d.decision==="include").length,eligibilityEvaluated=eds.filter(e=>e.decision!=="pending").length,eligibilityPending=eds.filter(e=>e.decision==="pending").length,eligibilityExcluded=eds.filter(e=>e.decision==="exclude"),finalInc=eds.filter(e=>e.decision==="include").length,sources=prismaSources(ss.analysisSessionId);return `${head("Diagrama PRISMA 2020",esc(ss.name),`<button id="print-prisma" type="button" class="btn btn-outline no-print">Baixar PDF</button>`)}<div class="prisma-flow" aria-label="Fluxograma PRISMA 2020"><section class="prisma-stage identification"><div class="prisma-phase">1. Identificação</div><div class="prisma-main"><div class="prisma-node primary"><b>Registros identificados nas bases de dados</b><span>${sources}</span><strong>Total (n = ${identified})</strong></div><div class="prisma-down" aria-hidden="true">↓</div><div class="prisma-node"><b>Duplicatas removidas antes da triagem</b><strong>n = ${dups}</strong></div></div></section><section class="prisma-stage screening"><div class="prisma-phase">2. Triagem</div><div class="prisma-main"><div class="prisma-node primary"><b>Registros triados por título, resumo e palavras-chave</b><strong>n = ${screened}</strong>${screenPending?`<small>Aguardando decisão: n = ${screenPending}</small>`:""}</div></div><aside class="prisma-exit"><h3>Registros excluídos após a triagem <span>(n = ${screenExcluded.length})</span></h3>${prismaReasons(screenExcluded)}</aside></section><section class="prisma-stage eligibility-stage"><div class="prisma-phase">3. Elegibilidade</div><div class="prisma-main"><div class="prisma-node primary"><b>Artigos encaminhados para avaliação em texto completo</b><strong>n = ${forwarded}</strong></div><div class="prisma-down" aria-hidden="true">↓</div><div class="prisma-node"><b>Artigos em texto completo avaliados para elegibilidade</b><strong>n = ${eligibilityEvaluated}</strong>${eligibilityPending?`<small>Aguardando decisão: n = ${eligibilityPending}</small>`:""}</div></div><aside class="prisma-exit"><h3>Artigos em texto completo excluídos <span>(n = ${eligibilityExcluded.length})</span></h3>${prismaReasons(eligibilityExcluded)}</aside></section><section class="prisma-stage inclusion"><div class="prisma-phase">4. Inclusão</div><div class="prisma-main"><div class="prisma-node final"><b>Estudos incluídos no corpus analítico final</b><strong>n = ${finalInc}</strong></div></div></section></div><div class="prisma-note"><b>Nota metodológica.</b> Os totais são atualizados automaticamente a partir da deduplicação, da triagem de títulos e resumos e da avaliação de elegibilidade. As justificativas são reproduzidas conforme registradas pelo avaliador.</div>`}

const quickSpecies=["Oreochromis niloticus","Cichla ocellaris","Poecilia reticulata","Arapaima gigas","Cyprinus carpio","Litopenaeus vannamei"];
function mapPage(){return `${head("Mapa de Espécies","Explore ocorrências georreferenciadas disponibilizadas pela API pública do GBIF.")}<section class="species-map-layout"><aside class="card species-map-panel"><form id="gbif-form"><div class="field"><label>Nome científico</label><input name="species" placeholder="Ex.: Oreochromis niloticus" required autocomplete="off"></div><div class="grid map-year-grid"><div class="field"><label>Ano inicial</label><input name="y1" type="number" value="2004" min="1500" max="2100"></div><div class="field"><label>Ano final</label><input name="y2" type="number" value="2025" min="1500" max="2100"></div></div><button type="submit" class="btn btn-primary map-search-button">Consultar GBIF</button></form><div class="quick-species"><h2>Seleção rápida</h2><p class="muted">Clique em uma espécie para carregar suas ocorrências.</p>${quickSpecies.map(name=>`<button type="button" class="quick-species-button" data-species="${name}"><span class="species">${name}</span><span aria-hidden="true">›</span></button>`).join("")}</div><div class="map-legend" aria-label="Legenda do mapa"><span><i class="legend-dot manual"></i>Busca manual</span><span><i class="legend-dot quick"></i>Seleção rápida</span></div><div class="notice map-quality"><b>Qualidade dos dados</b><br>A presença no GBIF não confirma estabelecimento ou invasividade. Verifique identificação, coordenadas, data e fonte.</div></aside><section class="species-map-area"><div id="gbif-status" class="map-status" role="status" aria-live="polite">Digite uma espécie ou use a seleção rápida para carregar as ocorrências.</div><div id="species-map" aria-label="Mapa interativo de ocorrências de espécies"></div><div class="map-attribution-note">Mapa: OpenStreetMap · Ocorrências: GBIF</div></section></section>`}
function initSpeciesMap(){const container=$("#species-map");if(!container)return;if(!window.L){container.innerHTML='<div class="notice danger-note">Não foi possível carregar o mapa interativo. Verifique sua conexão.</div>';return}speciesMap=window.L.map(container,{zoomControl:true}).setView([-14.2,-51.9],4);window.L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(speciesMap);speciesLayer=window.L.layerGroup().addTo(speciesMap);setTimeout(()=>speciesMap?.invalidateSize(),0)}
function occurrencePopup(row){return `<div class="occurrence-popup"><b class="species">${esc(row.species)}</b><dl><dt>Estado</dt><dd>${esc(row.state||"Não informado")}</dd><dt>Município</dt><dd>${esc(row.municipality||"Não informado")}</dd><dt>Corpo d'água</dt><dd>${esc(row.waterBody||"Não informado")}</dd><dt>Coordenadas</dt><dd>${row.lat.toFixed(5)}, ${row.lon.toFixed(5)}</dd><dt>Ano</dt><dd>${esc(row.year||"Não informado")}</dd></dl><a href="https://www.gbif.org/occurrence/${encodeURIComponent(row.key)}" target="_blank" rel="noopener">Ver registro no GBIF ↗</a></div>`}
async function gbifSearch(form,source="manual",forcedName=""){const f=new FormData(form),name=String(forcedName||f.get("species")||"").trim(),y1=Number(f.get("y1")),y2=Number(f.get("y2")),status=$("#gbif-status");if(!name)return toast("Informe o nome científico.");if(!y1||!y2||y1>y2)return toast("Confira o período informado.");form.elements.species.value=name;status.className="map-status loading";status.textContent=`Consultando ocorrências de ${name} no GBIF…`;form.querySelector('button[type="submit"]').disabled=true;try{const speciesResponse=await fetch(`https://api.gbif.org/v1/species/match?name=${encodeURIComponent(name)}`);if(!speciesResponse.ok)throw new Error("falha na identificação do táxon");const species=await speciesResponse.json();if(!species.usageKey)throw new Error("táxon não encontrado");const params=new URLSearchParams({taxon_key:species.usageKey,country:"BR",year:`${y1},${y2}`,has_coordinate:"true",limit:"300"});const totalParams=new URLSearchParams({taxon_key:species.usageKey,country:"BR",year:`${y1},${y2}`,limit:"0"});const [occurrenceResponse,totalResponse]=await Promise.all([fetch(`https://api.gbif.org/v1/occurrence/search?${params}`),fetch(`https://api.gbif.org/v1/occurrence/search?${totalParams}`)]);if(!occurrenceResponse.ok||!totalResponse.ok)throw new Error("falha na consulta de ocorrências");const [data,totalData]=await Promise.all([occurrenceResponse.json(),totalResponse.json()]);const rows=data.results.filter(r=>Number.isFinite(r.decimalLatitude)&&Number.isFinite(r.decimalLongitude)).slice(0,300).map(r=>({id:uid(),owner:state.user.id,key:r.key,species:r.scientificName||species.scientificName||name,lat:r.decimalLatitude,lon:r.decimalLongitude,state:r.stateProvince||r.gadm?.level1?.name||"",municipality:r.municipality||r.county||r.locality||"",waterBody:r.waterBody||r.verbatimLocality||r.habitat||"",year:r.year||String(r.eventDate||"").slice(0,4),dataset:r.datasetTitle||"GBIF"}));state.occurrences.push(...rows.filter(r=>!state.occurrences.some(x=>x.key===r.key)));save();speciesLayer?.clearLayers();const color=source==="quick"?"#f97316":"#0f766e",bounds=[];rows.forEach(row=>{window.L.circleMarker([row.lat,row.lon],{radius:6,color:"#fff",weight:1.5,fillColor:color,fillOpacity:.88}).bindPopup(occurrencePopup(row),{maxWidth:300}).addTo(speciesLayer);bounds.push([row.lat,row.lon])});if(bounds.length===1)speciesMap.setView(bounds[0],9);else if(bounds.length>1)speciesMap.fitBounds(bounds,{padding:[28,28],maxZoom:10});else speciesMap.setView([-14.2,-51.9],4);const scientificName=species.scientificName||name;status.className=`map-status ${source}`;status.innerHTML=`<span><b class="species">${esc(scientificName)}</b></span><span><b>${rows.length}</b> registro(s) plotado(s) de <b>${Number(totalData.count).toLocaleString("pt-BR")}</b> ocorrência(s) existentes no GBIF</span>`;activity("gbif_search",`Mapa carregado para ${scientificName}: ${rows.length} de ${totalData.count} ocorrências`)}catch(e){speciesLayer?.clearLayers();status.className="map-status error";status.textContent=`Não foi possível consultar o GBIF: ${e.message}.`}finally{form.querySelector('button[type="submit"]').disabled=false}}

let pendingVosArticles=[],pendingVosFiles=null;
function vosPage(){const sessions=mine(state.sessions);return `${head("VOSviewer Online","Carregue um arquivo bibliográfico, escolha a rede e visualize o mapa diretamente no navegador.",'<a class="btn btn-outline" href="https://app.vosviewer.com/docs/" target="_blank" rel="noopener">Documentação oficial ↗</a>')}<section class="vos-workflow"><article class="card vos-control-card"><div class="vos-step"><span>1</span><div><h2>Escolha os dados</h2><p>Use uma sessão da EcoMétrica ou carregue uma exportação em BibTeX, RIS ou CSV.</p></div></div><div class="vos-form-grid"><div class="field"><label for="vos-session">Sessão da EcoMétrica</label><select id="vos-session"><option value="">Selecione uma sessão</option>${sessions.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.articleCount-(s.duplicateCount||0)} registro(s)</option>`).join("")}</select></div><div class="field"><label for="vos-file">Ou carregue um arquivo</label><input id="vos-file" type="file" accept=".bib,.ris,.csv,text/csv"></div></div><div id="vos-file-status" class="vos-file-status">Nenhum arquivo externo carregado.</div><div class="vos-step"><span>2</span><div><h2>Configure a rede</h2><p>O limite elimina itens muito raros e melhora a leitura do mapa.</p></div></div><div class="vos-form-grid"><div class="field"><label for="vos-kind">Tipo de rede</label><select id="vos-kind"><option value="authors">Coautoria entre autores</option><option value="keywords">Coocorrência de palavras-chave</option></select></div><div class="field"><label for="vos-min">Mínimo de ocorrências</label><input id="vos-min" type="number" min="1" max="100" value="2"></div></div><button id="vos-generate" class="btn btn-primary vos-generate">Gerar mapa bibliométrico</button><div id="vos-generation-status" aria-live="polite"></div></article><article class="card vos-preview-card"><div class="vos-step"><span>3</span><div><h2>Prévia da rede</h2><p>Confira os itens e as relações antes de abrir no visualizador oficial.</p></div></div><div id="vos-preview" class="vos-preview-empty"><b>Aguardando dados</b><span>Selecione uma sessão ou carregue um arquivo para gerar a rede.</span></div></article></section><section id="vos-online-section" class="card vos-online-card"><div class="vos-online-head"><div class="vos-step"><span>4</span><div><h2>VOSviewer Online incorporado</h2><p>Depois de gerar, clique em <b>Open</b> no painel abaixo e selecione juntos os arquivos <i>map</i> e <i>network</i> baixados.</p></div></div><a class="btn btn-outline" href="https://app.vosviewer.com/" target="_blank" rel="noopener">Abrir em tela cheia ↗</a></div><div id="vos-embed-placeholder" class="vos-embed-placeholder"><b>Visualizador pronto para carregar</b><span>O carregamento sob demanda evita que a página desça automaticamente.</span><button id="vos-load-online" class="btn btn-primary">Carregar VOSviewer Online</button></div><iframe id="vos-online-frame" class="hidden" title="VOSviewer Online" data-src="https://app.vosviewer.com/" referrerpolicy="no-referrer" allow="fullscreen"></iframe><p class="vos-privacy">Os arquivos são processados localmente pela EcoMétrica. O painel incorporado pertence ao VOSviewer Online, da Leiden University.</p></section>`}
function vosSourceArticles(){const sid=$("#vos-session")?.value;return pendingVosArticles.length?pendingVosArticles:state.articles.filter(a=>a.sessionId===sid&&!a.isDuplicate)}
function cleanVosValue(value){const clean=String(value||"").replace(/[\t\r\n]+/g," ").trim().replaceAll('"','""');return /[,;]/.test(clean)?`"${clean}"`:clean}
function buildVosFiles(arts,kind,minOccurrences=2){const field=kind==="authors"?"authors":"keywords",counts={},pairs={};arts.forEach(article=>{const terms=splitTerms(article[field],kind);terms.forEach(t=>counts[t]=(counts[t]||0)+1);for(let i=0;i<terms.length;i++)for(let j=i+1;j<terms.length;j++){const key=[terms[i],terms[j]].sort().join("\u0001");pairs[key]=(pairs[key]||0)+1}});const labels=Object.keys(counts).filter(label=>counts[label]>=minOccurrences).sort((a,b)=>counts[b]-counts[a]||a.localeCompare(b)),ids=Object.fromEntries(labels.map((label,i)=>[label,i+1])),edges=Object.entries(pairs).map(([key,strength])=>{const [a,b]=key.split("\u0001");return {a,b,strength}}).filter(e=>ids[e.a]&&ids[e.b]).sort((a,b)=>b.strength-a.strength),map="id\tlabel\tweight<Documents>\n"+labels.map(label=>`${ids[label]}\t${cleanVosValue(label)}\t${counts[label]}`).join("\n"),network=edges.map(e=>`${ids[e.a]}\t${ids[e.b]}\t${e.strength}`).join("\n");return {labels,counts,edges,map,network,previewArticles:arts.map(article=>({...article,[field]:splitTerms(article[field],kind).filter(x=>ids[x]).join("; ")}))}}
async function handleVosFile(file){pendingVosArticles=[];pendingVosFiles=null;if(!file){$("#vos-file-status").textContent="Nenhum arquivo externo carregado.";return}try{const text=await file.text(),ext=file.name.split(".").pop().toLowerCase(),rows=ext==="csv"?parseCSV(text):ext==="ris"?parseRIS(text):ext==="bib"?parseBib(text):[];if(!rows.length)throw new Error("nenhum registro bibliográfico válido foi reconhecido");pendingVosArticles=rows;$("#vos-session").value="";$("#vos-file-status").innerHTML=`<span class="badge green">${rows.length} registro(s)</span> ${esc(file.name)}`;$("#vos-preview").innerHTML='<b>Arquivo pronto</b><span>Escolha o tipo de rede e clique em “Gerar mapa bibliométrico”.</span>';toast("Arquivo bibliográfico carregado.")}catch(error){$("#vos-file-status").innerHTML=`<span class="badge red">Falha</span> ${esc(error.message)}`;toast("Não foi possível ler o arquivo.")}}
function generateVos(){const arts=vosSourceArticles(),kind=$("#vos-kind").value,min=Math.max(1,+$("#vos-min").value||1);if(!arts.length)return toast("Selecione uma sessão ou carregue um arquivo válido.");const files=buildVosFiles(arts,kind,min);if(files.labels.length<2)return toast("A rede precisa de pelo menos dois itens no limite escolhido.");pendingVosFiles={...files,kind};const label=kind==="authors"?"coautoria":"palavras-chave";$("#vos-preview").innerHTML=networkGraph(files.previewArticles,kind,`Rede de ${label}`);bindNetworkInteractions();$("#vos-generation-status").innerHTML=`<div class="notice vos-ready"><b>Rede pronta:</b> ${files.labels.length} itens e ${files.edges.length} ligações.<div class="actions"><button class="btn btn-primary" id="vos-download-pair">Baixar arquivos para o VOSviewer</button><button class="btn btn-outline" id="vos-go-online">Ir ao VOSviewer Online ↓</button></div></div>`;$("#vos-download-pair").onclick=downloadVosPair;$("#vos-go-online").onclick=()=>$("#vos-online-section").scrollIntoView({behavior:"smooth"})}
function downloadVosPair(){if(!pendingVosFiles)return;const suffix=pendingVosFiles.kind==="authors"?"coautoria":"palavras-chave";download(`ecometrica-${suffix}-map.txt`,pendingVosFiles.map);setTimeout(()=>download(`ecometrica-${suffix}-network.txt`,pendingVosFiles.network),250);toast("Dois arquivos gerados: map e network.")}
function adminPage(){return `${head("Administração","Backup local e informações da instalação.")}<section class="grid two-col"><article class="card"><h2>Backup dos dados</h2><p class="muted">Exporte periodicamente uma cópia. Os dados desta versão ficam somente no navegador.</p><div class="actions"><button id="backup-export" class="btn btn-primary">Exportar backup</button><label class="btn btn-outline">Importar backup<input id="backup-import" type="file" accept="application/json" hidden></label></div></article><article class="card"><h2>Instalação PWA</h2><p class="muted">Use a opção “Instalar aplicativo” do navegador. Após o primeiro carregamento, a plataforma funciona offline, exceto o GBIF.</p><button id="install-app" class="btn btn-primary">Instalar EcoMétrica</button></article><article class="card"><h2>Conta atual</h2><p><b>${esc(state.user.name)}</b><br>${esc(state.user.email)}<br>${esc(state.user.institution||"")}</p><span class="badge green">${esc(state.user.role)}</span></article><article class="card"><h2>Armazenamento</h2><p>${state.sessions.length} sessões · ${state.articles.length} artigos · ${state.activities.length} atividades</p><button id="clear-demo" class="btn btn-danger">Limpar dados científicos</button></article></section>`}

function page(){if(!authReady)return `<div class="auth-wrap"><div class="card auth-card"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><p class="muted">Conectando com segurança…</p></div></div>`;if(authLoadError)return `<div class="auth-wrap"><div class="card auth-card"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><h1>Não foi possível carregar</h1><p class="muted">Verifique a conexão com a internet e tente novamente.</p><button class="btn btn-primary" id="retry-load" type="button">Tentar novamente</button></div></div>`;const r=route(),path=r.split("?")[0],[base,id]=path.split("/");if(!state.user)return path==="login"?authPage("login"):path==="register"?authPage("register"):landing();const pages={dashboard:dashboard,projects:projectsPage,search:searchPage,map:mapPage,corpus:corpusPage,sessions:sessionsPage,quality:qualityPage,screening:screeningPage,eligibility:eligibilityPage,prisma:prismaPage,results:resultsPage,vosviewer:vosPage,admin:adminPage};return shell(base==="session"?sessionDetail(id):base==="screen"?screenDetail(id):base==="eligibility"?eligibilityPage(id):(pages[base]||dashboard)())}
function render(){const currentRoute=route(),hadPageHead=!!document.querySelector(".page-head");if(speciesMap){speciesMap.remove();speciesMap=null;speciesLayer=null}$("#app").innerHTML=page();bind();const hasPageHead=!!document.querySelector(".page-head");if(currentRoute!==renderedRoute||(!hadPageHead&&hasPageHead)){renderedRoute=currentRoute;requestAnimationFrame(()=>window.scrollTo(0,0));setTimeout(()=>window.scrollTo(0,0),120)}}

function bind(){
  $$(".help-trigger").forEach(button=>button.addEventListener("click",openHelpGuide));
  $("#retry-load")?.addEventListener("click",()=>location.reload());
  $("#cite-ecometrica")?.addEventListener("click",openCitationGenerator);
  $$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
  $("#menu-toggle")?.addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
  bindNetworkInteractions();
  $("#logout")?.addEventListener("click",async()=>{await supabaseClient.auth.signOut();state.user=null;cloudProjects=[];cloudStrategies=[];cloudExecutions=[];go("home");render()});
  $("#new-project")?.addEventListener("click",()=>{creatingProject=true;render()});
  $$('.project-list-item').forEach(button=>button.addEventListener("click",()=>{activeProjectId=button.dataset.projectId;creatingProject=false;localStorage.setItem(ACTIVE_PROJECT_KEY,activeProjectId);render()}));
  $("#project-form")?.addEventListener("submit",e=>{e.preventDefault();saveProject(e.currentTarget)});
  $$('.execution-form').forEach(form=>form.addEventListener("submit",e=>{e.preventDefault();saveExecution(e.currentTarget)}));
  $("#google-login")?.addEventListener("click",async()=>{const button=$("#google-login");button.disabled=true;button.textContent="Abrindo Google…";const redirectTo="https://egbertomesquita-cmd.github.io/ecometrica-pwa/?auth=google";const {error}=await supabaseClient.auth.signInWithOAuth({provider:"google",options:{redirectTo}});if(error){toast(`Não foi possível abrir o Google: ${error.message}`);button.disabled=false;button.innerHTML='<span class="google-mark" aria-hidden="true">G</span>Continuar com Google'}});
  $("#auth-form")?.addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type="submit"]'),f=new FormData(form),email=String(f.get("email")).toLowerCase(),password=String(f.get("password"));button.disabled=true;button.textContent="Aguarde…";try{if(route()==="register"){const {data,error}=await supabaseClient.auth.signUp({email,password,options:{data:{full_name:f.get("name"),institution:f.get("institution")}}});if(error)throw error;if(!data.session){toast("Cadastro criado. Confirme o e-mail antes de entrar.");setTimeout(()=>go("login"),1200);return}await hydrateUser(data.user)}else{const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;await hydrateUser(data.user)}go("dashboard");render()}catch(error){toast(authMessage(error.message));button.disabled=false;button.textContent=route()==="register"?"Criar conta":"Entrar"}});
  const searchForm=$("#search-form");searchForm?.addEventListener("submit",e=>{e.preventDefault();renderStrategies(e.currentTarget)});
  $$('input[name="geography"]').forEach(input=>input.addEventListener("change",e=>$("#brazil-steps")?.classList.toggle("hidden",e.target.value!=="brazil")));
  $$('input[name="biome"]').forEach(input=>input.addEventListener("change",e=>{const select=$("#state-select"),states=brazilStates[e.target.value]||[];select.innerHTML=`<option value="">Selecione um estado</option>${states.map(([code,name])=>`<option value="${code}">${name} (${code})</option>`).join("")}`;$("#state-filter").classList.remove("hidden");$("#organism-filter").classList.add("hidden");$("#environment-filter").classList.add("hidden");select.value="";$$('input[name="organism"],input[name="environment"]').forEach(x=>x.checked=false)}));
  $("#state-select")?.addEventListener("change",e=>{$("#organism-filter").classList.toggle("hidden",!e.target.value);$("#environment-filter").classList.add("hidden");$$('input[name="organism"],input[name="environment"]').forEach(x=>x.checked=false)});
  $$('input[name="organism"]').forEach(input=>input.addEventListener("change",()=>{$("#environment-filter").classList.remove("hidden");$("#aquatic-type-filter").classList.add("hidden");$("#continental-type-filter").classList.add("hidden");$$('input[name="environment"],input[name="aquatic_type"],input[name="continental_type"]').forEach(x=>x.checked=false)}));
  $$('input[name="environment"]').forEach(input=>input.addEventListener("change",e=>{const aquatic=e.target.value==="aquatic";$("#aquatic-type-filter").classList.toggle("hidden",!aquatic);$("#continental-type-filter").classList.add("hidden");$$('input[name="aquatic_type"],input[name="continental_type"]').forEach(x=>x.checked=false)}));
  $$('input[name="aquatic_type"]').forEach(input=>input.addEventListener("change",e=>{$("#continental-type-filter").classList.toggle("hidden",e.target.value!=="continental");$$('input[name="continental_type"]').forEach(x=>x.checked=false)}));
  if(searchForm){
   const generateButton=$(".generate-search",searchForm);generateButton?.insertAdjacentHTML("afterend",'<button class="btn btn-outline reset-search" id="reset-search" type="button">↺ Resetar busca</button><small class="search-draft-note">O rascunho desta busca é salvo automaticamente neste navegador.</small>');
   restoreSearchDraft(searchForm);const updateDraft=()=>saveSearchDraft(searchForm,false);searchForm.addEventListener("change",updateDraft);searchForm.addEventListener("input",updateDraft);
   $("#reset-search")?.addEventListener("click",()=>{if(!confirm("Resetar toda a busca atual, incluindo as strings geradas?"))return;clearSearchDraft();lastGeneratedStrategy=null;render();toast("Busca resetada.")})
  }
  $("#search-help")?.addEventListener("click",()=>toast("Escolha Mundo ou complete Bioma, Estado, Organismo e Ambiente para o Brasil. Depois selecione descritores, bases, idioma e período."));
  $("#strategies")?.addEventListener("click",e=>{if(e.target.dataset.go)go(e.target.dataset.go);if(e.target.classList.contains("copy-strategy")){navigator.clipboard.writeText(e.target.closest(".card").querySelector(".strategy").innerText);toast("Estratégia copiada.")}if(e.target.id==="save-strategy")openSaveStrategy();if(e.target.id==="export-strategies"){const t=$$(".strategy").map(x=>x.innerText).join("\n\n");download("estrategias-ecometrica.txt",t)}});
  $("#corpus-files")?.addEventListener("change",e=>handleFiles(e.target.files));
  $("#corpus-preview")?.addEventListener("click",e=>{if(e.target.id==="save-import")saveImport()});
  $$('.dedup-decision').forEach(button=>button.addEventListener("click",()=>decideDuplicate(button.dataset.auditId,button.dataset.decision)));
  $("#export-dedup-audit")?.addEventListener("click",()=>exportDedupAudit(route().split("/")[1]));
  $("#confirm-dedup")?.addEventListener("click",()=>{const id=route().split("/")[1],s=state.sessions.find(x=>x.id===id),audits=ensureDedupAudits(id),pending=audits.filter(x=>x.decision==="pending").length;if(pending)return toast(`Revise os ${pending} par(es) pendente(s) antes de concluir.`);s.deduplicationConfirmed=true;s.deduplicationConfirmedAt=now();s.deduplicationReviewerId=state.user.id;s.deduplicationReviewerName=state.user.name;s.duplicateCount=audits.filter(x=>x.decision==="remove").length;save();activity("dedup_confirmed",`Deduplicação concluída em “${s.name}”: ${s.duplicateCount} registro(s) removido(s)`,s.name);toast("Deduplicação concluída e auditada.");render()});
  $("#export-session")?.addEventListener("click",()=>{const id=route().split("/")[1],arts=state.articles.filter(a=>a.sessionId===id),keys=["title","authors","journal","year","doi","keywords","source","isDuplicate"];download("sessao-ecometrica.csv",keys.join(",")+"\n"+arts.map(a=>keys.map(k=>`"${String(a[k]??"").replaceAll('"','""')}"`).join(",")).join("\n"),"text/csv")});
  $("#article-filter")?.addEventListener("input",filterArticles);$("#dup-filter")?.addEventListener("change",filterArticles);
  $("#quality-session")?.addEventListener("change",e=>location.hash=`#/quality?session=${encodeURIComponent(e.target.value)}`);$("#quality-export")?.addEventListener("click",exportQuality);$("#quality-filter")?.addEventListener("input",e=>{const sid=$("#quality-session").value,q=norm(e.target.value),rows=metadataQuality(sid).issueRows.filter(r=>!q||norm(`${r.article.title} ${r.article.authors} ${r.issues.join(" ")}`).includes(q));$("#quality-table").innerHTML=qualityTable(rows)});
  const updateAnalysisRoute=()=>{const session=$("#result-session")?.value||"",scope=$("#analysis-scope")?.value||"deduplicated";location.hash=`#/results?session=${encodeURIComponent(session)}&scope=${encodeURIComponent(scope)}`};$("#result-session")?.addEventListener("change",updateAnalysisRoute);$("#analysis-scope")?.addEventListener("change",updateAnalysisRoute);$("#print-results")?.addEventListener("click",()=>print());
  $("#new-screening")?.addEventListener("click",createScreening);$$('.decision').forEach(b=>b.onclick=()=>decide(route().split("/")[1],b.dataset.decision));$("#eligibility-session")?.addEventListener("change",e=>go(`eligibility/${e.target.value}`));$$('.elig').forEach(b=>b.onclick=()=>decideEligibility(route().split("/")[1],b.dataset.decision));
  $("#print-prisma")?.addEventListener("click",exportPrismaPdf);
  if($("#gbif-form")){initSpeciesMap();$("#gbif-form").addEventListener("submit",e=>{e.preventDefault();gbifSearch(e.currentTarget,"manual")});$$('.quick-species-button').forEach(button=>button.addEventListener("click",()=>gbifSearch($("#gbif-form"),"quick",button.dataset.species)))}
  $("#vos-file")?.addEventListener("change",e=>handleVosFile(e.target.files[0]));$("#vos-session")?.addEventListener("change",()=>{pendingVosArticles=[];pendingVosFiles=null;$("#vos-file").value="";$("#vos-file-status").textContent="Usando a sessão selecionada da EcoMétrica."});$("#vos-generate")?.addEventListener("click",generateVos);
  $("#vos-load-online")?.addEventListener("click",()=>{const frame=$("#vos-online-frame");frame.src=frame.dataset.src;frame.classList.remove("hidden");$("#vos-embed-placeholder").classList.add("hidden")});
  $("#backup-export")?.addEventListener("click",()=>download(`ecometrica-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2),"application/json"));
  $("#backup-import")?.addEventListener("change",async e=>{try{state=JSON.parse(await e.target.files[0].text());save();toast("Backup restaurado.");render()}catch{toast("Backup inválido.")}});
  $("#clear-demo")?.addEventListener("click",()=>{if(confirm("Remover sessões, artigos, decisões e atividades deste dispositivo?")){state={...state,sessions:[],articles:[],deduplicationAudits:[],screeningSessions:[],screeningDecisions:[],eligibilityDecisions:[],activities:[],occurrences:[]};save();render()}});
  $("#install-app")?.addEventListener("click",async()=>{if(window.installPrompt){window.installPrompt.prompt();await window.installPrompt.userChoice;window.installPrompt=null}else toast("Use o menu do navegador para instalar.")});
}
function filterArticles(){const id=route().split("/")[1],q=norm($("#article-filter").value),d=$("#dup-filter").value;const arts=state.articles.filter(a=>a.sessionId===id&&(!q||norm(`${a.title} ${a.authors} ${a.doi}`).includes(q))&&(d==="all"||(d==="duplicate")===a.isDuplicate));$("#article-table").innerHTML=articleTable(arts)}

window.addEventListener("hashchange",()=>{window.scrollTo(0,0);render()});window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();window.installPrompt=e});
if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js"));
function authMessage(message=""){if(/invalid login credentials/i.test(message))return "E-mail ou senha inválidos.";if(/user already registered/i.test(message))return "E-mail já cadastrado.";if(/password/i.test(message))return "A senha deve ter pelo menos 8 caracteres.";return `Não foi possível autenticar: ${message}`}
async function hydrateUser(user){if(!user){state.user=null;return}const {data:profile}=await supabaseClient.from("profiles").select("email, full_name, institution, role").eq("id",user.id).single();state.user={id:user.id,email:user.email,name:profile?.full_name||user.user_metadata?.full_name||user.email.split("@")[0],institution:profile?.institution||user.user_metadata?.institution||"",role:profile?.role||"researcher"}}
function scrubAuthSecrets(){if(!/(?:access_token|refresh_token|provider_token)=/.test(location.hash))return false;history.replaceState(null,"",`${location.pathname}${location.search}#/dashboard`);return true}
function finishOAuth(){const returning=new URLSearchParams(location.search).get("auth")==="google";const scrubbed=scrubAuthSecrets();if(returning&&!scrubbed)history.replaceState(null,"",`${location.pathname}#/dashboard`);return returning||scrubbed}
async function initAuth(){try{const {data:{session}}=await supabaseClient.auth.getSession();await hydrateUser(session?.user||null);if(session?.user){await loadCloudResearchData();finishOAuth()}}catch(error){console.error("Falha ao iniciar autenticação",error)}finally{authReady=true;render()}}
function loadExternalScript(src){return new Promise((resolve,reject)=>{const script=document.createElement("script");script.src=src;script.async=true;script.onload=resolve;script.onerror=()=>{script.remove();reject(new Error(`Falha ao carregar ${src}`))};document.head.appendChild(script)})}
async function initializeSupabase(){
 if(!window.supabase?.createClient){
  const sources=["https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2","https://unpkg.com/@supabase/supabase-js@2"];
  for(const source of sources){try{await loadExternalScript(source);if(window.supabase?.createClient)break}catch(error){console.warn(error.message)}}
 }
 if(!window.supabase?.createClient)throw new Error("Serviço de autenticação indisponível.");
 supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:false}});
 const pending=window.__ECOMETRICA_OAUTH;
 if(pending?.access_token&&pending?.refresh_token){
  const {error}=await supabaseClient.auth.setSession({access_token:pending.access_token,refresh_token:pending.refresh_token});
  delete window.__ECOMETRICA_OAUTH;
  if(error)throw error;
 }
}
function listenToAuth(){supabaseClient.auth.onAuthStateChange((event,session)=>{if(event==="SIGNED_IN"&&session?.user)setTimeout(async()=>{await hydrateUser(session.user);try{await loadCloudResearchData()}catch(error){console.error("Falha ao carregar projetos",error)}authReady=true;finishOAuth();if(["home","login","register","auth-callback"].includes(route()))go("dashboard");render()},0);if(authReady&&event==="SIGNED_OUT"){state.user=null;cloudProjects=[];cloudStrategies=[];cloudExecutions=[];render()}})}
async function bootstrap(){render();try{await initializeSupabase();listenToAuth();await initAuth()}catch(error){console.error("Falha ao carregar a EcoMétrica",error);delete window.__ECOMETRICA_OAUTH;authLoadError=error.message||"Falha de conexão";authReady=true;render()}}
bootstrap();
